package cn.cccs7.cynexus.market.application.service;
import cn.cccs7.cynexus.market.api.dto.*; import cn.cccs7.cynexus.market.api.request.*; import cn.cccs7.cynexus.market.domain.portfolio.*; import java.time.OffsetDateTime; import java.util.List; import org.springframework.stereotype.Service;
@Service public class PortfolioTradePlanAppService { private static final String P="workspace-user",T="default"; private final PortfolioTradePlanRepository repo; public PortfolioTradePlanAppService(PortfolioTradePlanRepository r){repo=r;} public List<PortfolioTradePlanDTO> list(String symbol){return repo.list(P,T,symbol).stream().map(this::dto).toList();} public PortfolioTradePlanDTO save(PortfolioTradePlanRequest r){return dto(repo.save(P,T,new PortfolioTradePlanBO(null,r.getSymbol(),PortfolioInstrumentType.fromPayload(r.getInstrumentType()),r.getStrategy(),r.getThesis(),r.getPlannedEntryPrice(),r.getStopLossPrice(),r.getTargetPrice(),r.getPlannedPositionPct(),r.getRiskAmount(),r.getExpectedHoldingDays(),r.getConfidenceScore(),r.getMarketRegime(),OffsetDateTime.now())));} private PortfolioTradePlanDTO dto(PortfolioTradePlanBO x){return PortfolioTradePlanDTO.builder().planId(x.planId()).symbol(x.symbol()).instrumentType(x.instrumentType().name()).strategy(x.strategy()).thesis(x.thesis()).plannedEntryPrice(x.plannedEntryPrice()).stopLossPrice(x.stopLossPrice()).targetPrice(x.targetPrice()).plannedPositionPct(x.plannedPositionPct()).riskAmount(x.riskAmount()).expectedHoldingDays(x.expectedHoldingDays()).confidenceScore(x.confidenceScore()).marketRegime(x.marketRegime()).createdAt(x.createdAt()).build();} }
